import { useCallback, useEffect, useState } from 'react';

export type AppTheme = 'light' | 'dark';

const STORAGE_KEY = 'app-theme';

function readInitialTheme(): AppTheme {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'light' || saved === 'dark') return saved;
  } catch {
    // localStorage может быть недоступен (приватный режим, SSR) — игнорируем
  }
  if (typeof window !== 'undefined' && window.matchMedia?.('(prefers-color-scheme: dark)').matches) {
    return 'dark';
  }
  return 'light';
}

/** Текущая тема приложения с сохранением выбора пользователя. */
export function useAppTheme() {
  const [theme, setTheme] = useState<AppTheme>(readInitialTheme);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, theme);
    } catch {
      // ничего страшного, просто не запомним выбор
    }
  }, [theme]);

  const toggleTheme = useCallback(() => {
    setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
  }, []);

  return { theme, setTheme, toggleTheme };
}
EOF
cat > src/router.ts <<'EOF'
import { useEffect, useState } from 'react';

export const routes = {
  home: '/',
  about: '/about',
  settings: '/settings',
} as const;

export type Route = (typeof routes)[keyof typeof routes];

const knownRoutes = new Set<string>(Object.values(routes));

/** Превращает hash вида `#/about` в маршрут; неизвестные пути ведут на главную. */
export function parseHash(hash: string): Route {
  const path = hash.replace(/^#/, '') || '/';
  return knownRoutes.has(path) ? (path as Route) : routes.home;
}

/** Ссылка для навигации по приложению. */
export function hrefFor(route: Route): string {
  return `#${route}`;
}

/** Текущий маршрут на основе `location.hash`; обновляется при переходах и кнопках «назад/вперёд». */
export function useHashRoute(): Route {
  const [route, setRoute] = useState<Route>(() => parseHash(window.location.hash));

  useEffect(() => {
    const onHashChange = () => setRoute(parseHash(window.location.hash));
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  return route;
}
EOF
